/**
 * The rail's character button, inlined.
 *
 * A `require()`d PNG draws as an empty box in the Android release build.
 * The drawable is in the APK and correctly named (`drawable/assets_
 * iconcharacters`, mdpi, valid file) — it is the runtime resolver that
 * fails: with `expo-updates` enabled, `expo-asset` looks local images up in
 * the embedded update manifest, which lists 24 assets and none of the app's
 * own. Declaring `assetBundlePatterns` does not change that count.
 *
 * The language flags hit exactly this and were fixed the same way. 192px
 * covers the 56pt rail button and the 58pt badge on her detail page at 3x.
 */
export const ICON_CHARACTERS = "data:image/png;base64,";
